Here’s a self-contained app using Python and SQLite. It stores registrations, prevents duplicate emails, and enforces the 20-seat limit even when people sign up simultaneously.

Save as `app.py` and run `python app.py`. Then open **http://localhost:8000**.

```python
import json
import re
import sqlite3
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

DB = "workshop.db"
CAPACITY = 20

with sqlite3.connect(DB) as db:
    db.execute("""
        CREATE TABLE IF NOT EXISTS registrations (
            id INTEGER PRIMARY KEY,
            name TEXT NOT NULL,
            email TEXT NOT NULL COLLATE NOCASE UNIQUE,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        )
    """)

HTML = """<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workshop signup</title>
  <style>
    body {
      font: 16px/1.5 system-ui, sans-serif;
      background: #f3f5fa;
      color: #172033;
      margin: 0;
      padding: 2rem 1rem;
    }
    main {
      max-width: 440px;
      margin: 4rem auto;
      padding: 2rem;
      background: white;
      border-radius: 14px;
      box-shadow: 0 8px 30px #17203315;
    }
    h1 { margin-top: 0; }
    label { display: block; margin: 1rem 0 .3rem; font-weight: 600; }
    input, button {
      box-sizing: border-box;
      width: 100%;
      padding: .75rem;
      font: inherit;
      border-radius: 8px;
    }
    input { border: 1px solid #aab4c5; }
    button {
      margin-top: 1.4rem;
      border: 0;
      background: #3458db;
      color: white;
      font-weight: 600;
      cursor: pointer;
    }
    button:disabled { background: #929bad; cursor: not-allowed; }
    #message { min-height: 1.5em; }
  </style>
</head>
<body>
  <main>
    <h1>Workshop signup</h1>
    <p id="availability" aria-live="polite">Checking availability…</p>
    <form id="signup">
      <label for="name">Name</label>
      <input id="name" name="name" maxlength="100" required autocomplete="name">

      <label for="email">Email</label>
      <input id="email" name="email" type="email" maxlength="254"
             required autocomplete="email">

      <button id="submit" type="submit" disabled>Reserve my seat</button>
    </form>
    <p id="message" role="status"></p>
  </main>
  <script>
    const form = document.querySelector('#signup');
    const button = document.querySelector('#submit');
    const availability = document.querySelector('#availability');
    const message = document.querySelector('#message');

    async function refresh() {
      try {
        const response = await fetch('/api/availability', {cache: 'no-store'});
        if (!response.ok) throw new Error();
        const data = await response.json();
        availability.textContent = data.remaining
          ? `${data.remaining} of 20 seats available`
          : 'This workshop is full.';
        button.disabled = data.remaining === 0;
      } catch {
        availability.textContent = 'Could not check availability. Please reload.';
        button.disabled = true;
      }
    }

    form.addEventListener('submit', async event => {
      event.preventDefault();
      button.disabled = true;
      message.textContent = 'Reserving your seat…';
      try {
        const response = await fetch('/api/signup', {
          method: 'POST',
          headers: {'Content-Type': 'application/json'},
          body: JSON.stringify({
            name: form.name.value,
            email: form.email.value
          })
        });
        const data = await response.json();
        message.textContent = data.message;
        if (response.ok) form.reset();
      } catch {
        message.textContent = 'Could not complete signup. Please try again.';
      }
      await refresh();
    });

    refresh();
  </script>
</body>
</html>"""


class Handler(BaseHTTPRequestHandler):
    def send_json(self, status, data):
        body = json.dumps(data).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        if self.path == "/":
            body = HTML.encode()
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        elif self.path == "/api/availability":
            with sqlite3.connect(DB) as db:
                count = db.execute("SELECT COUNT(*) FROM registrations").fetchone()[0]
            self.send_json(200, {"remaining": max(0, CAPACITY - count)})
        else:
            self.send_error(404)

    def do_POST(self):
        if self.path != "/api/signup":
            self.send_error(404)
            return

        try:
            length = int(self.headers.get("Content-Length", "0"))
            if length <= 0 or length > 4096:
                raise ValueError()
            data = json.loads(self.rfile.read(length))
            name = data["name"].strip()
            email = data["email"].strip()
            if (
                not name or len(name) > 100 or len(email) > 254
                or not re.fullmatch(r"[^\\s@]+@[^\\s@]+\\.[^\\s@]+", email)
            ):
                raise ValueError()
        except (ValueError, TypeError, KeyError, AttributeError):
            self.send_json(400, {"message": "Please enter a valid name and email."})
            return

        with sqlite3.connect(DB, timeout=10) as db:
            # Lock the database before checking capacity and inserting.
            db.execute("BEGIN IMMEDIATE")
            if db.execute(
                "SELECT 1 FROM registrations WHERE email = ?", (email,)
            ).fetchone():
                self.send_json(409, {"message": "This email is already registered."})
                return
            count = db.execute("SELECT COUNT(*) FROM registrations").fetchone()[0]
            if count >= CAPACITY:
                self.send_json(409, {"message": "Sorry, the workshop is full."})
                return
            db.execute(
                "INSERT INTO registrations (name, email) VALUES (?, ?)",
                (name, email),
            )
            db.commit()

        self.send_json(201, {"message": "You're registered! Your seat is reserved."})


if __name__ == "__main__":
    print("Open http://localhost:8000")
    ThreadingHTTPServer(("127.0.0.1", 8000), Handler).serve_forever()
```

Registrations are saved in `workshop.db`. This local version confirms on screen; it does not send confirmation emails.

